script.setup:
// glMatrix does the transform math: every tile on a trefoil knot gets its frame
// as a quaternion, a flip rotation is multiplied in, and the result is packed
// into a per-instance model matrix for one instanced draw.
const mod = await ctx.utils.import("https://esm.sh/gl-matrix@3.4.4");
const { mat3, mat4, quat, vec3 } = mod.default ?? mod;
const gl = ctx.gl;
const ALONG = 520, ACROSS = 4, COUNT = ALONG * ACROSS;
const knot = (t, out) => vec3.set(out, Math.sin(t) + 2 * Math.sin(2 * t), Math.cos(t) - 2 * Math.cos(2 * t), -Math.sin(3 * t));
// Precompute each tile's resting frame (Frenet frame of the knot).
const P = vec3.create(), P1 = vec3.create(), P2 = vec3.create(), T = vec3.create(), N = vec3.create(), B = vec3.create(), A = vec3.create();
const tiles = [];
for (let i = 0; i < ALONG; i++) {
  const t = i / ALONG * Math.PI * 2, e = 1e-3;
  knot(t, P); knot(t + e, P1); knot(t - e, P2);
  vec3.normalize(T, vec3.sub(T, P1, P2));
  vec3.sub(A, vec3.add(A, P1, P2), vec3.scale(B, P, 2)); // second derivative
  vec3.normalize(B, vec3.cross(B, T, A));
  vec3.cross(N, B, T);
  const m = mat3.fromValues(...N, ...B, ...T); // columns: x = normal, y = binormal, z = tangent
  const q = quat.normalize(quat.create(), quat.fromMat3(quat.create(), m));
  for (let j = 0; j < ACROSS; j++) {
    const off = (j - (ACROSS - 1) / 2) * 0.19;
    tiles.push({ t: i / ALONG, q, pos: vec3.scaleAndAdd(vec3.create(), P, B, off) });
  }
}
const box = ctx.utils.createMesh(ctx.utils.geometry.box());
const inst = new Float32Array(COUNT * 17); // mat4 + side phase
const buf = gl.createBuffer();
gl.bindVertexArray(box.vao);
gl.bindBuffer(gl.ARRAY_BUFFER, buf);
gl.bufferData(gl.ARRAY_BUFFER, inst.byteLength, gl.DYNAMIC_DRAW);
for (let c = 0; c < 4; c++) {
  gl.enableVertexAttribArray(3 + c);
  gl.vertexAttribPointer(3 + c, 4, gl.FLOAT, false, 68, c * 16);
  gl.vertexAttribDivisor(3 + c, 1);
}
gl.enableVertexAttribArray(7);
gl.vertexAttribPointer(7, 1, gl.FLOAT, false, 68, 64);
gl.vertexAttribDivisor(7, 1);
gl.bindVertexArray(null);
const prog = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec3 a_position; layout(location=1) in vec3 a_normal;
layout(location=3) in vec4 m0; layout(location=4) in vec4 m1; layout(location=5) in vec4 m2; layout(location=6) in vec4 m3;
layout(location=7) in float a_t;
uniform mat4 u_vp; out vec3 v_n; out vec3 v_w; out float v_side; out float v_t;
void main() {
  mat4 m = mat4(m0, m1, m2, m3);
  vec4 w = m * vec4(a_position, 1.0);
  v_w = w.xyz; v_n = mat3(m) * a_normal; v_side = a_normal.x; v_t = a_t;
  gl_Position = u_vp * w;
}`, `#version 300 es
precision highp float;
in vec3 v_n; in vec3 v_w; in float v_side; in float v_t; out vec4 outColor;
uniform vec3 u_front, u_back, u_eye;
void main() {
  vec3 n = normalize(v_n), v = normalize(u_eye - v_w), l = normalize(vec3(0.4, 0.9, 0.6));
  // The tile's two big faces (local +x / -x) carry the two colors; edges are pale.
  vec3 base = v_side > 0.5 ? u_front : v_side < -0.5 ? u_back : vec3(0.9);
  base *= 0.85 + 0.3 * sin(v_t * 6.283 * 3.0);
  float d = max(dot(n, l), 0.0), sp = pow(max(dot(n, normalize(l + v)), 0.0), 48.0);
  vec3 c = base * (0.12 + 0.88 * d) + sp * 0.5 + base * 0.25 * pow(1.0 - abs(dot(n, v)), 2.0);
  outColor = vec4(pow(c, vec3(0.4545)), 1.0);
}`);
Object.assign(ctx.state, { mat4, quat, vec3, tiles, inst, buf, box, prog, COUNT,
  flip: quat.create(), q: quat.create(), m: mat4.create(), scale: vec3.fromValues(0.012, 0.17, 0.038),
  camera: ctx.utils.createOrbitCamera({ distance: 8.4, theta: 0.3, phi: 1.2, fov: 40, near: 0.1, far: 100, minDistance: 2, maxDistance: 30 }) });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, { mat4, quat } = s, [w, h] = ctx.resolution;
const zAxis = [0, 0, 1];
s.tiles.forEach((tile, i) => {
  // A wave travels along the knot; each tile flips 180 degrees about the tangent as it passes.
  // Every wave that has passed adds half a turn, so the angle stays continuous.
  const x = tile.t * u.u_waves - ctx.time * u.u_speed * 0.15, n = Math.floor(x);
  const k = Math.min(1, Math.max(0, (x - n) * 2.5 - 0.75));
  quat.setAxisAngle(s.flip, zAxis, Math.PI * (n + k * k * (3 - 2 * k)));
  quat.multiply(s.q, tile.q, s.flip);
  mat4.fromRotationTranslationScale(s.m, s.q, tile.pos, s.scale);
  s.inst.set(s.m, i * 17);
  s.inst[i * 17 + 16] = tile.t;
});
gl.bindBuffer(gl.ARRAY_BUFFER, s.buf);
gl.bufferSubData(gl.ARRAY_BUFFER, 0, s.inst);
s.camera.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
// glMatrix builds the view from the shared camera's eye/target; the knot itself turns slowly.
const view = mat4.lookAt(mat4.create(), s.camera.getEye(), s.camera.getTarget(), [0, 1, 0]);
const proj = mat4.perspective(mat4.create(), s.camera.fovFor(w / h) * Math.PI / 180, w / h, 0.1, 100);
const vp = mat4.multiply(mat4.create(), proj, mat4.multiply(view, view, mat4.fromYRotation(mat4.create(), ctx.time * 0.1)));
gl.enable(gl.DEPTH_TEST);
gl.clearColor(0.03, 0.03, 0.045, 1);
gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
gl.useProgram(s.prog);
ctx.utils.setUniforms(s.prog, { u_vp: vp, u_eye: s.camera.getEye(), u_front: u.u_front, u_back: u.u_back });
s.box.draw(gl.TRIANGLES, s.COUNT);
